graph_mermaid:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	intake(intake)
	forecast(forecast)
	diagnosis(diagnosis)
	composer(composer)
	simulation(simulation)
	critic(critic)
	supervisor(supervisor)
	ranker(ranker)
	explainer(explainer)
	stress(stress)
	verifier(verifier)
	conclude(conclude)
	rail(rail)
	station_crowd(station_crowd)
	venue(venue)
	last_mile(last_mile)
	__end__([<p>__end__</p>]):::last
	__start__ --> intake;
	composer -.-> ranker;
	composer -.-> simulation;
	critic --> supervisor;
	diagnosis -.-> conclude;
	diagnosis -.-> last_mile;
	diagnosis -.-> rail;
	diagnosis -.-> station_crowd;
	diagnosis -.-> venue;
	explainer --> verifier;
	forecast --> diagnosis;
	intake --> forecast;
	last_mile --> composer;
	rail --> composer;
	ranker --> explainer;
	ranker --> stress;
	simulation --> critic;
	station_crowd --> composer;
	stress --> verifier;
	supervisor -.-> composer;
	supervisor -.-> ranker;
	venue --> composer;
	verifier --> conclude;
	conclude --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
